packaging.version._validate_epoch:
def _validate_epoch(value: object, /) -> int:
    epoch = (value or 0)
    if (isinstance(epoch, int) and epoch >= 0):
        return epoch
    msg = f'epoch must be non-negative integer, got {epoch}'
    raise InvalidVersion(msg)

packaging.version._validate_dev:
def _validate_dev(value: object, /) -> tuple[(Literal['dev'], int)] | None:
    if value is None:
        return value
    if (isinstance(value, int) and value >= 0):
        return ('dev', value)
    msg = f'dev must be non-negative integer, got {value}'
    raise InvalidVersion(msg)

packaging.version._validate_release:
def _validate_release(value: object, /) -> tuple[(int, ...)]:
    release = ((0, ) if value is None else value)
    if (isinstance(release, tuple) and len(release) > 0 and all(((isinstance(i, int) and i >= 0) for i in release))):
        return release
    msg = f'release must be a non-empty tuple of non-negative integers, got {release}'
    raise InvalidVersion(msg)

packaging._manylinux._glibc_version_stri:
def _glibc_version_string_ctypes() -> str | None:
    """
    Fallback implementation of glibc_version_string using ctypes.
    """
    try:
        import ctypes
    except ImportError:
        return None
    try:
        process_namespace = ctypes.CDLL(None)
    except OSError:
        return None
    try:
        gnu_get_libc_version = process_namespace.gnu_get_libc_version
    except AttributeError:
        return None
    gnu_get_libc_version.restype = ctypes.c_char_p
    version_str: str = gnu_get_libc_version()
    if not isinstance(version_str, str):
        version_str = version_str.decode('ascii')
    return version_str

packaging.specifiers._nearest_non_prerel:
def _nearest_non_prerelease(v: _VersionOrBoundary) -> Version | None:
    """Smallest non-pre-release version at or above *v*, or None."""
    if v is None:
        return None
    if isinstance(v, _BoundaryVersion):
        inner = v.version
        if inner.is_prerelease:
            return inner.__replace__(pre=None, dev=None, local=None)
        k = (inner.post + 1 if inner.post is not None else 0)
        return inner.__replace__(post=k, local=None)
    if not v.is_prerelease:
        return v
    return v.__replace__(pre=None, dev=None, local=None)

packaging.specifiers._pep440_filter_prer:
def _pep440_filter_prereleases(iterable: Iterable[Any], key: Callable[([Any], UnparsedVersion)] | None) -> Iterator[Any]:
    """Filter per PEP 440: exclude prereleases unless no finals exist."""
    all_nonfinal: list[Any] = []
    arbitrary_strings: list[Any] = []
    found_final = False
    for item in iterable:
        parsed = _coerce_version((item if key is None else key(item)))
        if parsed is None:
            if found_final:
                yield item
            else:
                arbitrary_strings.append(item)
                all_nonfinal.append(item)
            continue
        if not parsed.is_prerelease:
            if not found_final:
                yield from arbitrary_strings
                found_final = True
            yield item
            continue
        if not found_final:
            all_nonfinal.append(item)
    if not found_final:
        yield from all_nonfinal

packaging.pylock._get_sequence_as:
def _get_sequence_as(d: Mapping[(str, Any)], expected_item_type: type[_T], target_item_type: Callable[([_T], _T2)], key: str) -> list[_T2] | None:
    """Get list value from dictionary and verify expected items type."""
    if value := _get_sequence(d, expected_item_type, key) is None:
        return None
    result = []
    try:
        for item in value:
            typed_item = target_item_type(item)
            result.append(typed_item)
    except Exception as e:
        raise PylockValidationError(e, context=f'{key}[{len(result)}]') from e
    return result

packaging.pylock._toml_value:
def _toml_value(key: str, value: Any) -> Any:
    if isinstance(value, (Version, Marker, SpecifierSet)):
        return str(value)
    if (isinstance(value, Sequence) and key == 'environments'):
        return [str(v) for v in value]
    return value
